import * as React from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'

export type CarouselProps = {
  slides: React.ReactNode[]
  'aria-label'?: string
}

/** Horizontal slides with scroll snapping. No autoplay: the reader moves it. */
export function Carousel({ slides, 'aria-label': ariaLabel = 'Carousel' }: CarouselProps) {
  const view = React.useRef<HTMLDivElement>(null)
  const [index, setIndex] = React.useState(0)

  const go = (i: number) => {
    const el = view.current
    if (!el) return
    const n = Math.max(0, Math.min(slides.length - 1, i))
    el.scrollTo({ left: (el.children[n] as HTMLElement).offsetLeft - el.offsetLeft, behavior: 'smooth' })
  }
  const onScroll = () => {
    const el = view.current
    if (!el) return
    const w = (el.children[0] as HTMLElement | undefined)?.offsetWidth ?? 1
    setIndex(Math.round(el.scrollLeft / w))
  }

  return (
    <div data-slot="carousel" role="region" aria-roledescription="carousel" aria-label={ariaLabel}>
      <div data-slot="carousel-viewport" ref={view} onScroll={onScroll} tabIndex={0}
        onKeyDown={(e) => { if (e.key === 'ArrowRight') { e.preventDefault(); go(index + 1) } if (e.key === 'ArrowLeft') { e.preventDefault(); go(index - 1) } }}>
        {slides.map((s, i) => (
          <div key={i} data-slot="carousel-slide" role="group" aria-roledescription="slide" aria-label={`${i + 1} / ${slides.length}`}>{s}</div>
        ))}
      </div>
      <div data-slot="carousel-footer">
        <div data-slot="carousel-dots">
          {slides.map((_, i) => <button key={i} type="button" data-slot="carousel-dot" data-active={i === index} aria-label={`Slide ${i + 1}`} onClick={() => go(i)} />)}
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--fp-space-2)' }}>
          <span data-slot="carousel-count">{index + 1} / {slides.length}</span>
          <button type="button" data-slot="button" data-variant="outline" data-size="icon" aria-label="Previous" disabled={index === 0} onClick={() => go(index - 1)} style={{ width: 'var(--fp-control-sm)', height: 'var(--fp-control-sm)' }}><ChevronLeft size={16} /></button>
          <button type="button" data-slot="button" data-variant="outline" data-size="icon" aria-label="Next" disabled={index === slides.length - 1} onClick={() => go(index + 1)} style={{ width: 'var(--fp-control-sm)', height: 'var(--fp-control-sm)' }}><ChevronRight size={16} /></button>
        </div>
      </div>
    </div>
  )
}

import * as React from 'react'
import { Checkbox as BaseCheckbox } from '@base-ui/react/checkbox'
import { Check, Minus } from 'lucide-react'

export type CheckboxProps = Omit<BaseCheckbox.Root.Props, 'className' | 'children' | 'render'> & {
  /** Text beside the box. A string label also becomes the accessible name unless aria-label is set. */
  label?: React.ReactNode
  /** Class for the wrapping label. */
  className?: string
}

/**
 * Controlled (`checked` + `onCheckedChange`) or uncontrolled (`defaultChecked`). Every Base UI
 * root prop passes through: id, name, value, required, readOnly, form, inputRef, aria-*.
 */
export function Checkbox({ label, className, ...props }: CheckboxProps) {
  const root = (
    <BaseCheckbox.Root aria-label={typeof label === 'string' ? label : undefined} className={label == null ? className : undefined} {...props}>
        <BaseCheckbox.Indicator
          keepMounted
          data-slot="checkbox-box"
          render={(indicatorProps, state) => (
            <span
              {...indicatorProps}
              data-state={state.indeterminate ? 'indeterminate' : state.checked ? 'checked' : 'unchecked'}
            >
              {state.indeterminate
                ? <Minus size={12} strokeWidth={2.5} />
                : state.checked
                  ? <Check size={12} strokeWidth={2.5} />
                  : null}
            </span>
          )}
        />
    </BaseCheckbox.Root>
  )
  // Without a label the box stands alone, so an outer <Label> or aria-label can name it.
  // An empty wrapping <label> would otherwise become its (empty) accessible name.
  if (label == null) return root
  return (
    <label data-slot="checkbox" data-disabled={props.disabled ? 'true' : 'false'} className={className}>
      {root}
      <span data-slot="checkbox-label">{label}</span>
    </label>
  )
}

import * as React from 'react'
import { ToggleGroup as BaseToggleGroup } from '@base-ui/react/toggle-group'
import { Toggle as BaseToggle } from '@base-ui/react/toggle'

export type ChipOption = { value: string; label: React.ReactNode; count?: number; disabled?: boolean }

type Common = {
  options: ChipOption[]
  /** sm 32 / md 40 / lg 48, same as Button */
  size?: 'sm' | 'md' | 'lg'
  disabled?: boolean
  'aria-label'?: string
}
export type ChipGroupProps = Common & (
  | { multiple?: false; value?: string; defaultValue?: string; onValueChange?: (value: string) => void }
  | { multiple: true; value?: string[]; defaultValue?: string[]; onValueChange?: (value: string[]) => void }
)

/**
 * Separate filter chips with gaps between them (unlike Segmented, which is one
 * joined bar). Unselected chips have a light line that turns ink on hover;
 * the selected chip is an ink block. An optional count sits after the label.
 * Single choice by default; `multiple` allows several.
 */
export function ChipGroup(props: ChipGroupProps) {
  const { options, size = 'md', disabled, multiple } = props
  const toArr = (v: string | string[] | undefined) => (v === undefined ? undefined : Array.isArray(v) ? v : [v])
  const [inner, setInner] = React.useState<string[]>(toArr(props.defaultValue) ?? [])
  const controlled = props.value !== undefined
  const current = controlled ? toArr(props.value)! : inner

  return (
    <BaseToggleGroup
      data-slot="chip-group"
      data-size={size}
      aria-label={props['aria-label']}
      value={current}
      multiple={!!multiple}
      disabled={disabled}
      onValueChange={(next) => {
        const arr = next as string[]
        // single choice: clicking the selected chip keeps it selected
        if (!multiple && arr.length === 0) return
        if (!controlled) setInner(arr)
        if (multiple) (props.onValueChange as ((v: string[]) => void) | undefined)?.(arr)
        else (props.onValueChange as ((v: string) => void) | undefined)?.(arr[0])
      }}
    >
      {options.map((o) => (
        <BaseToggle key={o.value} value={o.value} data-slot="chip" disabled={o.disabled}>
          <span>{o.label}</span>
          {o.count != null && <span data-slot="chip-count">{o.count}</span>}
        </BaseToggle>
      ))}
    </BaseToggleGroup>
  )
}

import * as React from 'react'
import { Check, Copy } from 'lucide-react'

/** Inline code. */
export function Code({ children }: { children: React.ReactNode }) {
  return <code data-slot="code">{children}</code>
}

/** A code sample on a light surface, with a copy button. */
export function CodeBlock({ code, label = 'TSX', copyLabel = 'Copy' }: { code: string; label?: string; copyLabel?: string }) {
  const [copied, setCopied] = React.useState(false)
  const copy = () => {
    navigator.clipboard?.writeText(code).then(() => {
      setCopied(true)
      setTimeout(() => setCopied(false), 1500)
    }).catch(() => {})
  }
  return (
    <div data-slot="code-block">
      <div data-slot="code-block-header">
        <span data-slot="code-block-label">{label}</span>
        <button data-slot="button" data-variant="ghost" data-size="icon" type="button" onClick={copy} title={copyLabel} aria-label={copyLabel} style={{ width: 'var(--fp-control-sm)', height: 'var(--fp-control-sm)', color: 'var(--fp-muted)' }}>
          {copied ? <Check size={16} /> : <Copy size={16} />}
        </button>
      </div>
      <pre data-slot="code-block-pre">{code}</pre>
    </div>
  )
}

import * as React from 'react'
import { ChevronDown } from 'lucide-react'
import { Accordion } from '@base-ui/react/accordion'

type CollapseItem = { key: string; title: React.ReactNode; children: React.ReactNode; disabled?: boolean }
export type CollapseProps = {
  items: CollapseItem[]
  /** Uncontrolled: keys open at first render. */
  defaultActive?: string[]
  /** Controlled: keys that are open. Pair with onActiveChange. */
  active?: string[]
  onActiveChange?: (keys: string[]) => void
  multiple?: boolean
  className?: string
}

export function Collapse({ items, defaultActive, active, onActiveChange, multiple = false, className }: CollapseProps) {
  const [internal, setInternal] = React.useState<string[]>(defaultActive ?? [])
  const current = active ?? internal
  return (
    <Accordion.Root
      value={current}
      multiple={multiple}
      onValueChange={(next) => {
        if (active === undefined) setInternal(next as string[])
        onActiveChange?.(next as string[])
      }}
      data-slot="collapse"
      className={className}
    >
      {items.map((item) => (
        <Accordion.Item value={item.key} disabled={item.disabled} data-slot="collapse-item" data-open={current.includes(item.key)} key={item.key}>
          <Accordion.Header render={(props) => <div {...props} />}>
            <Accordion.Trigger data-slot="collapse-trigger">
              <span>{item.title}</span>
              <ChevronDown data-slot="collapse-icon" size={16} />
            </Accordion.Trigger>
          </Accordion.Header>
          <Accordion.Panel data-slot="collapse-content" keepMounted>
            {item.children}
          </Accordion.Panel>
        </Accordion.Item>
      ))}
    </Accordion.Root>
  )
}

import { Combobox as BaseCombobox } from '@base-ui/react/combobox'
import { Check, ChevronDown, X } from 'lucide-react'

export type ComboboxOption = { value: string; label: string }

export type ComboboxProps = {
  options: ComboboxOption[]
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (value: string | null) => void
  placeholder?: string
  emptyText?: string
  disabled?: boolean
  'aria-label'?: string
  'aria-labelledby'?: string
  /** sm 32 / md 40 / lg 48, same as Button. `default` is an alias of `md`. */
  size?: 'sm' | 'md' | 'default' | 'lg'
  /** Form field name, submitted with the surrounding <form>. */
  name?: string
  required?: boolean
  id?: string
  className?: string
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Fires on every keystroke in the text box. */
  onInputValueChange?: (text: string) => void
  /** Accessible names of the clear and open buttons, for localized products. */
  clearLabel?: string
  openLabel?: string
}

const byValue = (options: ComboboxOption[], v?: string | null) => (v == null ? v : options.find((o) => o.value === v) ?? null)

/** A select you can type into. Filters as you type (Typeahead). */
export function Combobox({ options, value, defaultValue, onValueChange, placeholder = 'Search…', emptyText = 'No matches', disabled, 'aria-label': ariaLabel, 'aria-labelledby': labelledBy, size = 'md', name, required, id, className, open, defaultOpen, onOpenChange, onInputValueChange, clearLabel = 'Clear', openLabel = 'Open' }: ComboboxProps) {
  return (
    <BaseCombobox.Root
      items={options}
      value={value === undefined ? undefined : (byValue(options, value) as ComboboxOption)}
      defaultValue={byValue(options, defaultValue) ?? undefined}
      itemToStringLabel={(o: ComboboxOption) => o.label}
      isItemEqualToValue={(a: ComboboxOption, b: ComboboxOption) => a.value === b.value}
      onValueChange={(o) => onValueChange?.(o ? o.value : null)}
      disabled={disabled}
      name={name}
      required={required}
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      onInputValueChange={onInputValueChange}
    >
      <div data-slot="combobox" className={className}>
        <div data-slot="combobox-control" data-size={size === 'default' ? 'md' : size}>
          <BaseCombobox.Input data-slot="combobox-input" id={id} placeholder={placeholder} aria-label={ariaLabel} aria-labelledby={labelledBy} />
          <BaseCombobox.Clear data-slot="combobox-clear" aria-label={clearLabel}><X size={16} /></BaseCombobox.Clear>
          <BaseCombobox.Trigger data-slot="combobox-trigger" aria-label={openLabel}><ChevronDown size={16} /></BaseCombobox.Trigger>
        </div>
      </div>
      <BaseCombobox.Portal>
        <BaseCombobox.Positioner data-slot="combobox-positioner" sideOffset={4}>
          <BaseCombobox.Popup data-slot="combobox-content">
            <BaseCombobox.Empty data-slot="combobox-empty">{emptyText}</BaseCombobox.Empty>
            <BaseCombobox.List>
              {(o: ComboboxOption) => (
                <BaseCombobox.Item key={o.value} value={o} data-slot="combobox-item">
                  {o.label}
                  <BaseCombobox.ItemIndicator><Check size={16} /></BaseCombobox.ItemIndicator>
                </BaseCombobox.Item>
              )}
            </BaseCombobox.List>
          </BaseCombobox.Popup>
        </BaseCombobox.Positioner>
      </BaseCombobox.Portal>
    </BaseCombobox.Root>
  )
}

import * as React from 'react'
import { Dialog as BaseDialog } from '@base-ui/react/dialog'
import { Search } from 'lucide-react'
import { Kbd } from '@/components/ui/kbd'

export type Command = {
  id: string
  label: string
  group?: string
  icon?: React.ReactNode
  shortcut?: string
  keywords?: string[]
  onSelect: () => void
}

export type CommandPaletteProps = {
  commands: Command[]
  open?: boolean
  onOpenChange?: (open: boolean) => void
  /** Bind ⌘K / Ctrl+K to open. On by default. */
  hotkey?: boolean
  placeholder?: string
  emptyText?: string
}

/** ⌘K search over a list of commands. Arrow keys move, Enter runs, Esc closes. */
export function CommandPalette({ commands, open: openProp, onOpenChange, hotkey = true, placeholder = 'Type a command or search…', emptyText = 'No results' }: CommandPaletteProps) {
  const [openState, setOpenState] = React.useState(false)
  const open = openProp ?? openState
  const setOpen = React.useCallback((o: boolean) => { setOpenState(o); onOpenChange?.(o) }, [onOpenChange])
  const [query, setQuery] = React.useState('')
  const [active, setActive] = React.useState(0)
  const listId = React.useId()

  React.useEffect(() => {
    if (!hotkey) return
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); setOpen(!open) }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [hotkey, open, setOpen])

  React.useEffect(() => { if (!open) { setQuery(''); setActive(0) } }, [open])

  const q = query.trim().toLowerCase()
  const results = q
    ? commands.filter((c) => [c.label, c.group ?? '', ...(c.keywords ?? [])].some((s) => s.toLowerCase().includes(q)))
    : commands
  const run = (c?: Command) => { if (!c) return; setOpen(false); c.onSelect() }

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); setActive((i) => Math.min(i + 1, results.length - 1)) }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setActive((i) => Math.max(i - 1, 0)) }
    else if (e.key === 'Enter') { e.preventDefault(); run(results[active]) }
  }

  let lastGroup: string | undefined
  return (
    <BaseDialog.Root open={open} onOpenChange={(o) => setOpen(o)}>
      <BaseDialog.Portal>
        <BaseDialog.Backdrop data-slot="dialog-overlay" />
        <BaseDialog.Popup data-slot="command-content" aria-label="Command palette">
          <div data-slot="command-input-row">
            <Search size={16} />
            <input
              data-slot="command-input"
              autoFocus
              value={query}
              placeholder={placeholder}
              onChange={(e) => { setQuery(e.target.value); setActive(0) }}
              onKeyDown={onKeyDown}
              role="combobox"
              aria-expanded="true"
              aria-controls={listId}
              aria-activedescendant={results[active] ? `${listId}-${results[active].id}` : undefined}
            />
            <Kbd>Esc</Kbd>
          </div>
          <div data-slot="command-list" id={listId} role="listbox">
            {results.length === 0 && <div data-slot="command-empty">{emptyText}</div>}
            {results.map((c, i) => {
              const header = c.group && c.group !== lastGroup ? c.group : null
              lastGroup = c.group
              return (
                <React.Fragment key={c.id}>
                  {header && <div data-slot="command-group">{header}</div>}
                  <button
                    type="button"
                    id={`${listId}-${c.id}`}
                    data-slot="command-item"
                    data-active={i === active}
                    role="option"
                    aria-selected={i === active}
                    tabIndex={-1}
                    onMouseMove={() => setActive(i)}
                    onClick={() => run(c)}
                  >
                    {c.icon}
                    <span>{c.label}</span>
                    {c.shortcut && <Kbd>{c.shortcut}</Kbd>}
                  </button>
                </React.Fragment>
              )
            })}
          </div>
        </BaseDialog.Popup>
      </BaseDialog.Portal>
    </BaseDialog.Root>
  )
}

