const UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ['year', 31536000], ['month', 2592000], ['week', 604800],
  ['day', 86400], ['hour', 3600], ['minute', 60], ['second', 1],
]

/** "3 minutes ago" for a date, in the given locale. */
export function formatRelative(date: Date, now = new Date(), locale?: string) {
  const diff = Math.round((date.getTime() - now.getTime()) / 1000)
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: 'auto' })
  for (const [unit, sec] of UNITS) {
    if (Math.abs(diff) >= sec || unit === 'second') return rtf.format(Math.round(diff / sec), unit)
  }
  return ''
}

export type TimestampProps = Omit<React.TimeHTMLAttributes<HTMLTimeElement>, 'dateTime' | 'children'> & {
  date: Date | string | number
  /** relative ("3 min ago"), date, or datetime */
  format?: 'relative' | 'date' | 'datetime'
  locale?: string
  /** Refresh relative text every N ms. Off by default. */
  refreshMs?: number
}

/** A <time> element: relative or absolute, with the full date on hover. */
export function Timestamp({ date, format = 'relative', locale, refreshMs, ...props }: TimestampProps) {
  const d = React.useMemo(() => new Date(date), [date])
  const [now, setNow] = React.useState(() => new Date())
  React.useEffect(() => {
    if (!refreshMs || format !== 'relative') return
    const id = setInterval(() => setNow(new Date()), refreshMs)
    return () => clearInterval(id)
  }, [refreshMs, format])
  const full = new Intl.DateTimeFormat(locale, { dateStyle: 'long', timeStyle: 'short' }).format(d)
  const text = format === 'relative'
    ? formatRelative(d, now, locale)
    : new Intl.DateTimeFormat(locale, format === 'date' ? { dateStyle: 'medium' } : { dateStyle: 'medium', timeStyle: 'short' }).format(d)
  return <time data-slot="timestamp" dateTime={d.toISOString()} title={full} {...props}>{text}</time>
}

import * as React from 'react'
import { Toast as BaseToast } from '@base-ui/react/toast'
import { CircleCheck, CircleAlert, Info, X } from 'lucide-react'

/*
 * Two ways to use toasts.
 *
 * 1. Request-local (apps with SSR): wrap the app in <ToastProvider> and call
 *    const toast = useToast(); toast.add({ title, description, type }) from components.
 *    Nothing is created at module load, so server rendering shares no state.
 * 2. Global (static sites, demos): mount <Toaster /> once, then call toast({ … }) from anywhere.
 */

export type ToastOptions = {
  title: React.ReactNode
  description?: React.ReactNode
  type?: 'default' | 'success' | 'error'
  /** ms before it closes; 0 keeps it open */
  timeout?: number
  action?: { label: string; onClick: () => void }
}

// Created on first use, never at import time.
let manager: ReturnType<typeof BaseToast.createToastManager> | undefined
const getManager = () => (manager ??= BaseToast.createToastManager())

export function toast({ title, description, type = 'default', timeout, action }: ToastOptions) {
  return getManager().add({
    title,
    description,
    type,
    timeout,
    actionProps: action ? { children: action.label, onClick: action.onClick } : undefined,
  })
}
toast.close = (id: string) => getManager().close(id)

/** The toast manager of the nearest <ToastProvider>: add, close, update, promise. */
export const useToast = BaseToast.useToastManager

const ICON = { default: Info, success: CircleCheck, error: CircleAlert }

function ToastList({ dismissLabel }: { dismissLabel: string }) {
  const { toasts } = BaseToast.useToastManager()
  return toasts.map((t) => {
    const type = (t.type ?? 'default') as keyof typeof ICON
    const Icon = ICON[type] ?? Info
    return (
      <BaseToast.Root key={t.id} toast={t} data-slot="toast" data-type={type}>
        <span data-slot="toast-icon"><Icon size={16} /></span>
        <BaseToast.Content data-slot="toast-body">
          <BaseToast.Title data-slot="toast-title" />
          <BaseToast.Description data-slot="toast-description" />
          {t.actionProps && <BaseToast.Action data-slot="button" data-variant="outline" data-size="sm" />}
        </BaseToast.Content>
        <BaseToast.Close data-slot="toast-close" aria-hidden={false} aria-label={dismissLabel}><X size={16} /></BaseToast.Close>
      </BaseToast.Root>
    )
  })
}

export type ToastViewportProps = {
  /** Accessible name of each close button, for localized products. */
  dismissLabel?: string
  /** Accessible name of the notification region. */
  regionLabel?: string
}

function ToastPortal({ dismissLabel = 'Close', regionLabel = 'Notifications' }: ToastViewportProps) {
  return (
    <BaseToast.Portal>
      <BaseToast.Viewport data-slot="toast-viewport" aria-label={regionLabel}>
        <ToastList dismissLabel={dismissLabel} />
      </BaseToast.Viewport>
    </BaseToast.Portal>
  )
}

/** Request-local toasts: provide once near the root, then use useToast() below it. */
export function ToastProvider({ children, timeout = 5000, limit = 3, ...labels }: ToastViewportProps & { children?: React.ReactNode; timeout?: number; limit?: number }) {
  return (
    <BaseToast.Provider timeout={timeout} limit={limit}>
      {children}
      <ToastPortal {...labels} />
    </BaseToast.Provider>
  )
}

/** Global toasts: mount once, then call toast({ … }) from anywhere. */
export function Toaster({ timeout = 4000, limit = 3, ...labels }: ToastViewportProps & { timeout?: number; limit?: number }) {
  return (
    <BaseToast.Provider toastManager={getManager()} timeout={timeout} limit={limit}>
      <ToastPortal {...labels} />
    </BaseToast.Provider>
  )
}

import * as React from 'react'
import { ToggleGroup as BaseToggleGroup } from '@base-ui/react/toggle-group'
import { Toggle as BaseToggle } from '@base-ui/react/toggle'

export type ToggleOption = { value: string; label: React.ReactNode; 'aria-label'?: string; disabled?: boolean }

export type ToggleGroupProps = {
  options: ToggleOption[]
  value?: string[]
  defaultValue?: string[]
  /** Allow several pressed at once (e.g. bold + italic). */
  multiple?: boolean
  size?: 'sm' | 'md'
  disabled?: boolean
  onValueChange?: (value: string[]) => void
}

/** Joined toggle buttons. Pressed items turn into an ink block. */
export function ToggleGroup({ options, value, defaultValue, multiple, size = 'md', disabled, onValueChange }: ToggleGroupProps) {
  return (
    <BaseToggleGroup
      data-slot="toggle-group"
      data-size={size}
      value={value}
      defaultValue={defaultValue}
      multiple={multiple}
      disabled={disabled}
      onValueChange={(v) => onValueChange?.(v as string[])}
    >
      {options.map((o) => (
        <BaseToggle key={o.value} value={o.value} data-slot="toggle" aria-label={o['aria-label']} disabled={o.disabled}>
          {o.label}
        </BaseToggle>
      ))}
    </BaseToggleGroup>
  )
}

/** A single on/off button. */
export function Toggle({ children, ...props }: React.ComponentProps<typeof BaseToggle>) {
  return <BaseToggle data-slot="toggle" {...props}>{children}</BaseToggle>
}

/** Buttons joined edge to edge, sharing one border. */
export function ButtonGroup({ children, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div data-slot="button-group" role="group" {...props}>{children}</div>
}

import * as React from 'react'
import { Toolbar as BaseToolbar } from '@base-ui/react/toolbar'
import { Toggle as BaseToggle } from '@base-ui/react/toggle'

/** A row of quiet actions above an editor or table. Arrow keys move between items. */
export function Toolbar({ children, ...props }: React.ComponentProps<typeof BaseToolbar.Root>) {
  return <BaseToolbar.Root data-slot="toolbar" {...props}>{children}</BaseToolbar.Root>
}

export function ToolbarGroup({ children, ...props }: React.ComponentProps<typeof BaseToolbar.Group>) {
  return <BaseToolbar.Group data-slot="toolbar-group" {...props}>{children}</BaseToolbar.Group>
}

export function ToolbarButton({ children, ...props }: React.ComponentProps<typeof BaseToolbar.Button>) {
  return <BaseToolbar.Button data-slot="toolbar-button" {...props}>{children}</BaseToolbar.Button>
}

/** A toolbar button that stays pressed (bold, italic …). */
export function ToolbarToggle({ children, pressed, defaultPressed, onPressedChange, ...props }: Omit<React.ComponentProps<typeof BaseToolbar.Button>, 'render'> & {
  pressed?: boolean
  defaultPressed?: boolean
  onPressedChange?: (pressed: boolean) => void
}) {
  return (
    <BaseToolbar.Button
      data-slot="toolbar-button"
      {...props}
      render={<BaseToggle pressed={pressed} defaultPressed={defaultPressed} onPressedChange={(p) => onPressedChange?.(p)} />}
    >
      {children}
    </BaseToolbar.Button>
  )
}

export function ToolbarSeparator() {
  return <BaseToolbar.Separator data-slot="toolbar-separator" />
}

/** Pushes the items after it to the far end. */
export function ToolbarSpacer() {
  return <span data-slot="toolbar-spacer" />
}

import * as React from 'react'
import { Tooltip as BaseTooltip } from '@base-ui/react/tooltip'

export type TooltipProps = {
  content: React.ReactNode
  side?: 'top' | 'bottom' | 'left' | 'right'
  align?: 'start' | 'center' | 'end'
  sideOffset?: number
  /** Controlled (`open` + `onOpenChange`) or uncontrolled (`defaultOpen`). */
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Milliseconds before it opens on hover. */
  delay?: number
  disabled?: boolean
  className?: string
  children: React.ReactElement
}

export function Tooltip({ content, side = 'top', align, sideOffset = 8, open, defaultOpen, onOpenChange, delay = 120, disabled, className, children }: TooltipProps) {
  return (
    <BaseTooltip.Provider delay={delay}>
      <BaseTooltip.Root open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange} disabled={disabled}>
        <BaseTooltip.Trigger render={<span data-slot="tooltip">{children}</span>} />
        <BaseTooltip.Portal>
          <BaseTooltip.Positioner data-slot="tooltip-positioner" side={side} align={align} sideOffset={sideOffset}>
            <BaseTooltip.Popup data-slot="tooltip-content" data-side={side} role="tooltip" className={className} style={{ pointerEvents: 'none' }}>
              {content}
            </BaseTooltip.Popup>
          </BaseTooltip.Positioner>
        </BaseTooltip.Portal>
      </BaseTooltip.Root>
    </BaseTooltip.Provider>
  )
}

/* ---- compound API: the full Base UI surface -------------------------------
 * <TooltipProvider delay={400}>…
 *   <TooltipRoot>
 *     <TooltipTrigger render={<Button aria-label="Filters" />}>…</TooltipTrigger>
 *     <TooltipContent>Filter the list</TooltipContent>
 *   </TooltipRoot>
 * </TooltipProvider>
 * The trigger gets aria-describedby pointing at the content, so the tooltip is also
 * read as a description of the control.
 */
export const TooltipProvider = BaseTooltip.Provider

const TooltipIdContext = React.createContext<string | undefined>(undefined)

export function TooltipRoot({ children, ...props }: Omit<BaseTooltip.Root.Props, 'children'> & { children?: React.ReactNode }) {
  const id = React.useId()
  return (
    <TooltipIdContext.Provider value={id}>
      <BaseTooltip.Root {...props}>{children}</BaseTooltip.Root>
    </TooltipIdContext.Provider>
  )
}

export function TooltipTrigger(props: BaseTooltip.Trigger.Props) {
  const id = React.useContext(TooltipIdContext)
  return (
    <BaseTooltip.Trigger
      {...props}
      aria-describedby={[props['aria-describedby'], id].filter(Boolean).join(' ') || undefined}
    />
  )
}

export type TooltipContentProps = Omit<BaseTooltip.Popup.Props, 'className'> & {
  className?: string
  side?: 'top' | 'bottom' | 'left' | 'right'
  align?: 'start' | 'center' | 'end'
  sideOffset?: number
}

export function TooltipContent({ className, side = 'top', align, sideOffset = 8, ...props }: TooltipContentProps) {
  const id = React.useContext(TooltipIdContext)
  return (
    <BaseTooltip.Portal>
      <BaseTooltip.Positioner data-slot="tooltip-positioner" side={side} align={align} sideOffset={sideOffset}>
        <BaseTooltip.Popup data-slot="tooltip-content" data-side={side} className={className} {...props} id={id} role="tooltip" />
      </BaseTooltip.Positioner>
    </BaseTooltip.Portal>
  )
}

import * as React from 'react'
import { ChevronRight, ChevronDown, Folder, FolderOpen, File as FileIcon } from 'lucide-react'

export type TreeNode = { id: string; label: React.ReactNode; children?: TreeNode[]; icon?: React.ReactNode }

export type TreeProps = {
  nodes: TreeNode[]
  defaultExpanded?: string[]
  selected?: string | null
  defaultSelected?: string | null
  onSelect?: (id: string) => void
  'aria-label'?: string
}

/** A file tree. Click a folder to open it; the selected row is an ink block. Arrow keys work like a file manager. */
export function Tree({ nodes, defaultExpanded = [], selected, defaultSelected = null, onSelect, 'aria-label': ariaLabel }: TreeProps) {
  const [open, setOpen] = React.useState<Set<string>>(() => new Set(defaultExpanded))
  const [inner, setInner] = React.useState<string | null>(defaultSelected)
  const current = selected !== undefined ? selected : inner
  const root = React.useRef<HTMLUListElement>(null)

  const toggle = (id: string, to?: boolean) => setOpen((s) => {
    const n = new Set(s)
    if (to ?? !n.has(id)) n.add(id); else n.delete(id)
    return n
  })
  const pick = (id: string) => { setInner(id); onSelect?.(id) }

  const onKeyDown = (e: React.KeyboardEvent) => {
    const items = Array.from(root.current?.querySelectorAll<HTMLButtonElement>('[data-slot="tree-item"]') ?? [])
    const i = items.indexOf(document.activeElement as HTMLButtonElement)
    if (i < 0) return
    const el = items[i]
    const id = el.dataset.id!
    const hasKids = el.dataset.branch === 'true'
    if (e.key === 'ArrowDown') { e.preventDefault(); items[i + 1]?.focus() }
    else if (e.key === 'ArrowUp') { e.preventDefault(); items[i - 1]?.focus() }
    else if (e.key === 'ArrowRight' && hasKids) { e.preventDefault(); toggle(id, true) }
    else if (e.key === 'ArrowLeft' && hasKids) { e.preventDefault(); toggle(id, false) }
  }

  const render = (list: TreeNode[], depth: number): React.ReactNode => (
    <ul data-slot="tree" role={depth === 0 ? 'tree' : 'group'} aria-label={depth === 0 ? ariaLabel : undefined} ref={depth === 0 ? root : undefined} onKeyDown={depth === 0 ? onKeyDown : undefined}>
      {list.map((n) => {
        const branch = !!n.children?.length
        const expanded = open.has(n.id)
        return (
          <li key={n.id} role="none">
            <button
              type="button"
              role="treeitem"
              data-slot="tree-item"
              data-id={n.id}
              data-branch={branch}
              data-selected={current === n.id}
              aria-expanded={branch ? expanded : undefined}
              aria-selected={current === n.id}
              onClick={() => { if (branch) toggle(n.id); pick(n.id) }}
            >
              <span data-slot="tree-chevron">{branch ? (expanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />) : null}</span>
              {n.icon ?? (branch ? (expanded ? <FolderOpen size={16} /> : <Folder size={16} />) : <FileIcon size={16} />)}
              <span>{n.label}</span>
            </button>
            {branch && expanded && render(n.children!, depth + 1)}
          </li>
        )
      })}
    </ul>
  )
  return <>{render(nodes, 0)}</>
}

import * as React from 'react'

/** Hidden on screen, still read by screen readers. */
export function VisuallyHidden({ children, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span data-slot="visually-hidden" {...props}>{children}</span>
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
